import ConsoleHandler, {ConsoleConfig} from './ConsoleHandler';
import SyslogHandler, {SyslogConfig} from './SyslogHandler';
import FileHandler, {FileConfig} from './FileHandler';
import {Output} from '../types';

export interface OutputHandlers {[key: string]: ConsoleHandler | SyslogHandler | FileHandler;}

export function getHandlers(
    topLevelNS: string,
    version: string,
    processName: string = 'unknown',
): OutputHandlers {
    return {
        [Output.console]: new ConsoleHandler(topLevelNS),
        [Output.syslog]: new SyslogHandler(topLevelNS, version, processName),
        [Output.file]: new FileHandler(topLevelNS, version, processName),
    };
}

export {
    ConsoleHandler,
    SyslogHandler,
    FileHandler,
    ConsoleConfig,
    SyslogConfig,
    FileConfig,
};
