import OutputHandler from './OutputHandler';
import {Level} from '../types';

/**
 * Console output configuration
 * @interface ConsoleConfig
 */
export interface ConsoleConfig {

    /**
     * Whether or not to add the filename and line number to each line logged
     * @name ConsoleConfig#outputFileAndLine
     * @type {boolean}
     */
    outputFileAndLine: boolean;

    /**
     * Whether or not to add the logging level to each line logged
     * @name ConsoleConfig#outputLevel
     * @type {boolean}
     */
    outputLevel?: boolean;
}

/**
 * ConsoleHandler class - logging to global.console
 * @class ConsoleHandler
 * @param {any} [_console = global.console] You may pass a alternative console
 */
export default class ConsoleHandler extends OutputHandler<ConsoleConfig> {

    // The console configuration loaded or defaulted
    private _config: ConsoleConfig;

    constructor(
        private _topLevelNS: string,
        private _console: Console = global.console,
    ) {
        super();
    }

    /**
     * Write to the console
     * @method ConsoleHandler#write
     * @param {string} namespace The Log namespace
     * @param {Level} level The level of logging
     * @param {any[]} ...args The arguments to log
     */
    public write(
        timestamp: Date,
        namespace: string,
        level: Level,
        ...args: any[],
    ): void {
        const fullNamespace =
            namespace && `${this._topLevelNS}.${namespace}`
            || this._topLevelNS;
        const logArgs = [];
        // Some trickery here to allow string substitutions and console styling
        if (args.length && typeof args[0] === 'string') {
            if (this._config && this._config.outputLevel) {
                logArgs.push(`${level} ${fullNamespace} ${args[0]}`);
            } else {
                logArgs.push(`${fullNamespace} ${args[0]}`);
            }
            logArgs.push(...args.slice(1));
        }
        // The default behavior is less tricky
        else {
            if (this._config && this._config.outputLevel) {
                logArgs.push(level);
            }
            logArgs.push(fullNamespace);
            logArgs.push(...args);
        }
        if (this._config && this._config.outputFileAndLine) {
            // The first four items on the stack are from jibo-log:
            // 1. Log#debug/info/warn/error
            // 2. Log#_log
            // 3. forEach(output: OutputHandler)
            // 4. OutputHandler#write
            logArgs.push(new Error().stack.split('\n')[4]);
        }
        switch(level) {
            case Level.debug:
                this._console.log(...logArgs);
                break;
            case Level.info:
                this._console.info(...logArgs);
                break;
            case Level.warn:
                this._console.warn(...logArgs);
                break;
            case Level.error:
                this._console.error(...logArgs);
                break;
        }
    }

    /**
     * The console output configuration for this handler
     * @name ConsoleHandler#config
     * @type {ConsoleConfig}
     */
    public set config(config: ConsoleConfig) {
        this._config = config;
    }
    public get config(): ConsoleConfig {
        return this._config;
    }
}
